visuals.code:
:root {
  color-scheme: light;
  --font-heading: "Plus Jakarta Sans", sans-serif;
  --font-body: "Be Vietnam Pro", sans-serif;
  --font-mono: "IBM Plex Mono", monospace;
  --color-primary: #000000;
  --color-background: #ffffff;
  --color-text: #141414;
  --color-secondary: #333333;
  --color-muted: #6b6b6b;
  --color-border: #e2e2e2;
  --color-surface: #f6f6f6;
  --color-info: #276ef1;
  --color-success: #048848;
  --color-warning: #ffc043;
  --color-danger: #e11900;
  --container-width: 1280px;
  --article-width: 760px;
  --thumbnail-ratio: 16 / 9;
  --space-xs: 4px;
  --space-sm: 8px;
  --space-md: 16px;
  --space-lg: 24px;
  --space-xl: 32px;
  --space-2xl: 48px;
  --space-3xl: 64px;
  --radius-button: 8px;
  --radius-image: 0px;
  --transition-fast: 180ms ease;
}
.editorial-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: var(--space-xl);
}
.editorial-thumbnail {
  display: block;
  width: 100%;
  aspect-ratio: var(--thumbnail-ratio);
  object-fit: cover;
}
@media (max-width: 1023px) {
  .editorial-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@media (max-width: 767px) {
  .editorial-grid { grid-template-columns: 1fr; }
  .article-toc--sidebar { display: none; }
}
